//! C-alignment regression tests (step H1b: how DML statements are driven). GENERATED by
//! target/perf-work/h1b/gen_tests.py. Each case is a script of SQL statements run on one
//! connection through the library API; the expected text is what the same script produces with
//! C SQLite 3.54.1 (driver target/perf-work/h1b/c/drv.c): every result row, then per statement
//! `= <rc> <extended rc> <message> | <changes> <total_changes> <last_insert_rowid> <autocommit>`.
use crate::{Connection, StepResult};
use sqliters_types::Value;

fn show(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_owned(),
        Value::Integer(i) => i.to_string(),
        Value::Real(r) => format!("r{:016x}", r.to_bits()),
        Value::Text(t) => format!("'{t}'"),
        Value::Blob(b) => format!(
            "x'{}'#{}",
            b.iter()
                .take(64)
                .map(|x| format!("{x:02x}"))
                .collect::<String>(),
            b.len()
        ),
    }
}

fn drive(script: &[&str]) -> Vec<String> {
    let conn = Connection::open_in_memory().unwrap();
    let mut out = Vec::new();
    for (i, line) in script.iter().enumerate() {
        let ln = i + 1;
        let mut res: Result<(), crate::SqliteError> = Ok(());
        match conn.prepare(line) {
            Ok(mut s) => {
                loop {
                    match s.step() {
                        Ok(StepResult::Row(r)) => {
                            let mut o = format!("{ln}");
                            for v in r.values() {
                                o.push('|');
                                o.push_str(&show(v));
                            }
                            out.push(o);
                        }
                        Ok(StepResult::Done) => break,
                        Err(e) => {
                            res = Err(e);
                            break;
                        }
                    }
                }
                if let Err(e) = s.finalize()
                    && res.is_ok()
                {
                    res = Err(e);
                }
            }
            Err(e) => res = Err(e),
        }
        let (rc, ext, msg) = match &res {
            Ok(()) => (0, 0, "ok".to_owned()),
            Err(e) => (e.code as i32 & 0xff, e.extended_code, e.message.clone()),
        };
        out.push(format!(
            "{ln} = {rc} {ext} {msg} | {} {} {} {}",
            conn.changes(),
            conn.total_changes(),
            conn.last_insert_rowid(),
            i32::from(conn.is_autocommit())
        ));
    }
    out
}

fn check(script: &[&str], expected: &[&str]) {
    let got = drive(script);
    let exp: Vec<String> = expected.iter().map(|s| (*s).to_owned()).collect();
    assert_eq!(got, exp, "\nscript: {script:#?}");
}

/// Differs from C without the step H1b changes.
#[test]
fn delete_two_pass_visits_rows_in_rowid_order() {
    check(
        &[
            "CREATE TABLE t(id INTEGER PRIMARY KEY,k INT);",
            "CREATE INDEX tk ON t(k);",
            "INSERT INTO t VALUES(1,2),(2,1),(3,9);",
            "CREATE TRIGGER tr AFTER DELETE ON t BEGIN DELETE FROM t WHERE id=old.id+1; END;",
            "DELETE FROM t WHERE k<5;",
            "SELECT id FROM t;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 3 3 3 1",
            "4 = 0 0 ok | 3 3 3 1",
            "5 = 0 0 ok | 1 5 3 1",
            "6|3",
            "6 = 0 0 ok | 1 5 3 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn delete_and_update_returning_follow_the_rowset_order() {
    check(
        &[
            "CREATE TABLE t(id INTEGER PRIMARY KEY,k INT);",
            "CREATE INDEX tk ON t(k);",
            "INSERT INTO t VALUES(1,2),(2,1),(3,9),(4,0);",
            "UPDATE t SET k=k+10 WHERE k<5 RETURNING id;",
            "DELETE FROM t WHERE k>10 RETURNING id;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 4 4 4 1",
            "4|1",
            "4|2",
            "4|4",
            "4 = 0 0 ok | 3 7 4 1",
            "5|1",
            "5|2",
            "5 = 0 0 ok | 2 9 4 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn last_insert_rowid_and_total_changes_survive_a_failed_statement() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY,b UNIQUE);",
            "CREATE TABLE log(m);",
            "CREATE TRIGGER tr BEFORE INSERT ON t BEGIN INSERT INTO log VALUES(new.a); END;",
            "INSERT INTO t VALUES(5,5);",
            "INSERT INTO t VALUES(10,1),(11,2),(12,5),(13,4);",
            "SELECT last_insert_rowid(), changes(), total_changes();",
            "BEGIN;",
            "INSERT OR FAIL INTO t VALUES(30,1),(31,2),(32,5),(33,4);",
            "SELECT last_insert_rowid(), changes(), total_changes();",
            "COMMIT;",
            "SELECT a FROM t ORDER BY a;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 0 0 0 1",
            "4 = 0 0 ok | 1 2 5 1",
            "5 = 19 2067 UNIQUE constraint failed: t.b | 0 5 11 1",
            "6|11|0|5",
            "6 = 0 0 ok | 0 5 11 1",
            "7 = 0 0 ok | 0 5 11 0",
            "8 = 19 2067 UNIQUE constraint failed: t.b | 2 10 31 0",
            "9|31|2|10",
            "9 = 0 0 ok | 2 10 31 0",
            "10 = 0 0 ok | 2 10 31 1",
            "11|5",
            "11|30",
            "11|31",
            "11 = 0 0 ok | 2 10 31 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn abort_without_statement_journal_keeps_the_rows_written_so_far() {
    check(
        &[
            "CREATE TABLE s(a INT, b TEXT) STRICT;",
            "CREATE TABLE q(x,y);",
            "INSERT INTO q VALUES(1,'a'),(2,'b'),('x','c'),(4,'d');",
            "BEGIN;",
            "INSERT INTO s SELECT x,y FROM q;",
            "SELECT * FROM s;",
            "SELECT changes(), total_changes();",
            "COMMIT;",
            "SELECT count(*) FROM s;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 4 4 4 1",
            "4 = 0 0 ok | 4 4 4 0",
            "5 = 19 3091 cannot store TEXT value in INT column s.a | 0 4 2 0",
            "6|1|'a'",
            "6|2|'b'",
            "6 = 0 0 ok | 0 4 2 0",
            "7|0|4",
            "7 = 0 0 ok | 0 4 2 0",
            "8 = 0 0 ok | 0 4 2 1",
            "9|2",
            "9 = 0 0 ok | 0 4 2 1",
        ],
    );
}

/// (also equal to C before this step)
#[test]
fn statement_journal_rolls_back_only_the_failed_statement() {
    check(
        &[
            "CREATE TABLE t(a,b);",
            "CREATE TABLE s(x);",
            "INSERT INTO s VALUES(100),(100000);",
            "BEGIN;",
            "INSERT INTO t SELECT x, x FROM s;",
            "INSERT INTO t SELECT 1, abs(x-100001-9223372036854775807) FROM s ORDER BY x DESC;",
            "SELECT count(*) FROM t;",
            "COMMIT;",
            "SELECT count(*) FROM t;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 2 2 2 1",
            "4 = 0 0 ok | 2 2 2 0",
            "5 = 0 0 ok | 2 4 2 0",
            "6 = 1 1 integer overflow | 0 4 2 0",
            "7|2",
            "7 = 0 0 ok | 0 4 2 0",
            "8 = 0 0 ok | 0 4 2 1",
            "9|2",
            "9 = 0 0 ok | 0 4 2 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn full_error_rolls_back_the_statement_only_with_a_statement_journal() {
    check(
        &[
            "PRAGMA max_page_count=20;",
            "CREATE TABLE t(a,b);",
            "CREATE TABLE s(x);",
            "INSERT INTO s VALUES(100),(100000);",
            "BEGIN;",
            "INSERT INTO t VALUES(1,2);",
            "INSERT INTO t SELECT x, x FROM s;",
            "INSERT INTO t SELECT 1, zeroblob(x) FROM s ORDER BY x DESC;",
            "SELECT count(*) FROM t;",
            "COMMIT;",
            "SELECT count(*) FROM t;",
            "BEGIN;",
            "INSERT INTO t VALUES(1,2);",
            "INSERT INTO t WITH r(n,z) AS (SELECT 1,x'00' UNION ALL SELECT n+1, z||z FROM r WHERE n<18) SELECT n,z FROM r;",
            "SELECT count(*) FROM t;",
            "COMMIT;",
            "SELECT count(*) FROM t;",
        ],
        &[
            "1|20",
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 0 0 0 1",
            "4 = 0 0 ok | 2 2 2 1",
            "5 = 0 0 ok | 2 2 2 0",
            "6 = 0 0 ok | 1 3 1 0",
            "7 = 0 0 ok | 2 5 3 0",
            "8 = 13 13 database or disk is full | 0 5 4 0",
            "9|3",
            "9 = 0 0 ok | 0 5 4 0",
            "10 = 0 0 ok | 0 5 4 1",
            "11|3",
            "11 = 0 0 ok | 0 5 4 1",
            "12 = 0 0 ok | 0 5 4 0",
            "13 = 0 0 ok | 1 6 4 0",
            "14 = 13 13 database or disk is full | 0 6 21 1",
            "15|3",
            "15 = 0 0 ok | 0 6 21 1",
            "16 = 1 1 cannot commit - no transaction is active | 0 6 21 1",
            "17|3",
            "17 = 0 0 ok | 0 6 21 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn strict_type_error_ignores_the_or_clause() {
    check(
        &[
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a INT, b TEXT) STRICT;",
            "INSERT OR IGNORE INTO t VALUES(1,1,'x'),(2,'bad','y'),(3,3,'z');",
            "SELECT * FROM t;",
            "INSERT OR IGNORE INTO t VALUES(1,'bad','y');",
            "INSERT OR REPLACE INTO t VALUES(4,4,'w');",
            "SELECT * FROM t;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 19 3091 cannot store TEXT value in INT column t.a | 0 0 1 1",
            "3 = 0 0 ok | 0 0 1 1",
            "4 = 19 3091 cannot store TEXT value in INT column t.a | 0 0 1 1",
            "5 = 0 0 ok | 1 1 4 1",
            "6|4|4|'w'",
            "6 = 0 0 ok | 1 1 4 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn unique_checks_run_in_index_list_order() {
    check(
        &[
            "CREATE TABLE t1(id INT PRIMARY KEY, a TEXT UNIQUE, d INT UNIQUE) WITHOUT ROWID;",
            "INSERT INTO t1 VALUES(4,'x',4);",
            "INSERT INTO t1 VALUES(4,'y',4);",
            "INSERT INTO t1 VALUES(4,'x',9);",
            "CREATE TABLE t9(id INTEGER PRIMARY KEY, a REAL, b TEXT);",
            "CREATE UNIQUE INDEX t9_i0 ON t9(b, b);",
            "CREATE UNIQUE INDEX t9_i1 ON t9(b) WHERE b IS NOT NULL;",
            "INSERT INTO t9 VALUES(1,1,'x'),(2,2,'y');",
            "UPDATE t9 SET b='';",
            "CREATE TABLE t3(id INT, a INT, b INT, c, PRIMARY KEY(id, a), UNIQUE(a, b)) WITHOUT ROWID;",
            "INSERT INTO t3 VALUES(1,1,1,1),(11,1,2,2);",
            "UPDATE t3 SET b=2, id=id+10 WHERE c=1;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 1 1 0 1",
            "3 = 19 2067 UNIQUE constraint failed: t1.d | 0 1 0 1",
            "4 = 19 2067 UNIQUE constraint failed: t1.a | 0 1 0 1",
            "5 = 0 0 ok | 0 1 0 1",
            "6 = 0 0 ok | 0 1 0 1",
            "7 = 0 0 ok | 0 1 0 1",
            "8 = 0 0 ok | 2 3 2 1",
            "9 = 19 2067 UNIQUE constraint failed: t9.b | 0 3 2 1",
            "10 = 0 0 ok | 0 3 2 1",
            "11 = 0 0 ok | 2 5 2 1",
            "12 = 19 2067 UNIQUE constraint failed: t3.a, t3.b | 0 5 2 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn autoincrement_counter_counts_rejected_rows() {
    check(
        &[
            "CREATE TABLE t(id INTEGER PRIMARY KEY AUTOINCREMENT, a UNIQUE ON CONFLICT IGNORE);",
            "INSERT INTO t VALUES(1,'x');",
            "INSERT INTO t VALUES(40,'x'),(NULL,'y');",
            "SELECT * FROM t;",
            "SELECT * FROM sqlite_sequence;",
            "INSERT INTO t(a) VALUES('x');",
            "INSERT INTO t(a) VALUES('z');",
            "SELECT * FROM t;",
            "SELECT * FROM sqlite_sequence;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 1 1 1 1",
            "3 = 0 0 ok | 1 2 41 1",
            "4|1|'x'",
            "4|41|'y'",
            "4 = 0 0 ok | 1 2 41 1",
            "5|'t'|41",
            "5 = 0 0 ok | 1 2 41 1",
            "6 = 0 0 ok | 0 2 41 1",
            "7 = 0 0 ok | 1 3 43 1",
            "8|1|'x'",
            "8|41|'y'",
            "8|43|'z'",
            "8 = 0 0 ok | 1 3 43 1",
            "9|'t'|43",
            "9 = 0 0 ok | 1 3 43 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn single_row_insert_halts_on_a_missing_parent_before_writing() {
    check(
        &[
            "PRAGMA foreign_keys=1;",
            "CREATE TABLE p(id INTEGER PRIMARY KEY);",
            "CREATE TABLE c(id INTEGER PRIMARY KEY, r REFERENCES p(id));",
            "INSERT INTO p VALUES(1);",
            "INSERT INTO c VALUES(5,1);",
            "INSERT INTO c VALUES(6,9);",
            "SELECT last_insert_rowid();",
            "INSERT INTO c VALUES(7,9),(8,1);",
            "SELECT last_insert_rowid();",
            "SELECT * FROM c;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 0 0 0 1",
            "4 = 0 0 ok | 1 1 1 1",
            "5 = 0 0 ok | 1 2 5 1",
            "6 = 19 787 FOREIGN KEY constraint failed | 0 2 5 1",
            "7|5",
            "7 = 0 0 ok | 0 2 5 1",
            "8 = 19 787 FOREIGN KEY constraint failed | 0 2 8 1",
            "9|8",
            "9 = 0 0 ok | 0 2 8 1",
            "10|5|1",
            "10 = 0 0 ok | 0 2 8 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn foreign_key_mismatch_is_a_prepare_error_for_the_statements_c_reports() {
    check(
        &[
            "PRAGMA foreign_keys=1;",
            "CREATE TABLE p(id INT, a INT, d INT, PRIMARY KEY(id, a));",
            "CREATE TABLE c(id INTEGER PRIMARY KEY, r REFERENCES p(id));",
            "INSERT INTO p VALUES(1,1,1),(2,2,2);",
            "UPDATE p SET d=7 WHERE a=1;",
            "SELECT * FROM p ORDER BY id;",
            "INSERT INTO c VALUES(1,1);",
            "DELETE FROM p WHERE a=2;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 0 0 0 1",
            "4 = 1 1 foreign key mismatch - \"c\" referencing \"p\" | 0 0 0 1",
            "5 = 0 0 ok | 0 0 0 1",
            "6 = 0 0 ok | 0 0 0 1",
            "7 = 1 1 foreign key mismatch - \"c\" referencing \"p\" | 0 0 0 1",
            "8 = 1 1 foreign key mismatch - \"c\" referencing \"p\" | 0 0 0 1",
        ],
    );
}

/// Differs from C without the step H1b changes.
#[test]
fn trigger_old_new_references_have_no_affinity_but_real_columns_are_real() {
    check(
        &[
            "CREATE TABLE t1(id INTEGER PRIMARY KEY, a TEXT, b);",
            "CREATE TABLE log(m);",
            "INSERT INTO t1 VALUES(1,'2',1),(2,'7',2);",
            "CREATE TRIGGER tr3 AFTER UPDATE ON t1 BEGIN INSERT INTO log SELECT 'eq '||old.id WHERE old.a=2; INSERT INTO log SELECT 'txt '||old.id WHERE old.a='2'; END;",
            "UPDATE t1 SET b=b+1;",
            "SELECT * FROM log;",
            "CREATE TABLE t(a REAL, b TEXT, c INT);",
            "CREATE VIEW v AS SELECT a, b, c FROM t;",
            "CREATE TRIGGER vi INSTEAD OF INSERT ON v BEGIN INSERT INTO log VALUES(typeof(new.a)||' '||new.a||' '||typeof(new.b)||' '||typeof(new.c)); END;",
            "INSERT INTO v VALUES(0, 5, '7');",
            "SELECT * FROM log;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 0 0 0 1",
            "3 = 0 0 ok | 2 2 2 1",
            "4 = 0 0 ok | 2 2 2 1",
            "5 = 0 0 ok | 2 5 2 1",
            "6|'txt 1'",
            "6 = 0 0 ok | 2 5 2 1",
            "7 = 0 0 ok | 2 5 2 1",
            "8 = 0 0 ok | 2 5 2 1",
            "9 = 0 0 ok | 2 5 2 1",
            "10 = 0 0 ok | 0 6 2 1",
            "11|'txt 1'",
            "11|'real 0.0 integer text'",
            "11 = 0 0 ok | 0 6 2 1",
        ],
    );
}

