/// Differs from C without the step H1b changes.
#[test]
fn delete_from_a_view_with_returning_needs_only_some_trigger() {
    check(
        &[
            "CREATE TABLE t(a,b);",
            "INSERT INTO t VALUES(1,2),(3,4);",
            "CREATE VIEW v AS SELECT a,b FROM t;",
            "CREATE TRIGGER vi INSTEAD OF INSERT ON v BEGIN INSERT INTO t VALUES(new.a,new.b); END;",
            "DELETE FROM v WHERE a=1 RETURNING a;",
            "DELETE FROM v WHERE a=1;",
            "SELECT count(*) FROM t;",
        ],
        &[
            "1 = 0 0 ok | 0 0 0 1",
            "2 = 0 0 ok | 2 2 2 1",
            "3 = 0 0 ok | 2 2 2 1",
            "4 = 0 0 ok | 2 2 2 1",
            "5|1",
            "5 = 0 0 ok | 0 2 2 1",
            "6 = 1 1 cannot modify v because it is a view | 0 2 2 1",
            "7|2",
            "7 = 0 0 ok | 0 2 2 1",
        ],
    );
}

